const body = $input.first().json.body;
const findings = body && Array.isArray(body.findings) ? body.findings : [];
const store = $getWorkflowStaticData('global');
store.seen = store.seen || {};
const MAX_LINES = 20;
const MAX_LINE_CHARS = 180;
const fps = [];
const lines = [];
const key = (f) => JSON.stringify([f.check_id, f.file, f.line, f.pattern]);
// forget fingerprints no longer reported, so a re-introduced finding alerts again
if (body && Array.isArray(body.findings)) {
  const current = new Set(findings.filter((f) => f && f.severity === 'high').map(key));
  for (const k of Object.keys(store.seen)) if (!current.has(k)) delete store.seen[k];
}
for (const f of findings) {
  if (!f || f.severity !== 'high') continue;
  const fp = key(f);
  if (store.seen[fp]) continue;
  if (lines.length >= MAX_LINES) break;
  fps.push(fp);
  lines.push((f.check_id + ' ' + f.file + ':' + f.line + ' ' + f.pattern).slice(0, MAX_LINE_CHARS));
}
return [{ json: { count: lines.length, fps, text: 'dev-guard: ' + lines.length + ' new high finding(s)\n' + lines.join('\n') } }];

// Runs only after Telegram succeeded, so a failed send is retried on the next scan.
const store = $getWorkflowStaticData('global');
store.seen = store.seen || {};
for (const fp of $('Filter New Highs').first().json.fps) store.seen[fp] = Date.now();
return $input.all();
